/**
 * Constructs an object of <code>MInternalFrame</code>.
 * 
 * @param title
 *            Title for this internal frame.
 * 
 */
public MInternalFrame(String title) {
	super(title, true, true, true, true);
	setDefaultCloseOperation(WindowConstants.DO_NOTHING_ON_CLOSE);
	glassPane = new MGlassPane();
	this.setGlassPane(glassPane);
}

/**
 * Sets the state of this internal frame to busy.
 * 
 * @param busy
 *            If this is <code>true</code>, all the mouse and key events are
 *            trapped and consumed. The cursor on this internal frame is
 *            seto a busy cursor.
 * 
 */
public void setBusy(boolean busy) {
	glassPane.setCursor(busy ? com.myjavaworld.gui.MGlassPane.BUSY_CURSOR
			: com.myjavaworld.gui.MGlassPane.NORMAL_CURSOR);
	glassPane.setVisible(busy);
	this.busy = busy;
}

/**
 * Tells whether or not this internal frame is in busy state.
 * 
 * @return <code>true</code>, if this internal frame is in busy state.
 *         <code>false</code>, otherwise.
 * 
 */
public boolean isBusy() {
	return busy;
}

private class MGlassPane extends com.myjavaworld.gui.MGlassPane {

	@Override

	 *            Title
	 * 
	 */
	public MFrame(String title) {
		this(title, new Insets(0, 0, 0, 0));
	}

	/**
	 * Constructs an object of <code>MFrame</code> with the given parameters.
	 * 
	 * @param title
	 *            Title for this frame.
	 * @param insets
	 *            Insets to set on the content pane of this frame.
	 * 
	 */
	public MFrame(String title, final Insets insets) {
		super(title);
		setContentPane(new JPanel() {

			@Override
			public Insets getInsets() {
				return insets;
			}
		});
		getContentPane().setLayout(new BorderLayout());
		glassPane = new MGlassPane();
		this.setGlassPane(glassPane);
	}

	/**
	 * Sets the state of this frame to the given state.
	 * 
	 * @param busy
	 *            If this is <code>true</code>, all mouse and key events will be
	 *            consumed and the cursor on the frame is set to a busy
	 *            (hour-glass) cursor. If false, the frame will have the regular
	 *            behaviour and cursor.
	 * 
	 */
	public void setBusy(boolean busy) {
		glassPane.setCursor(busy ? MGlassPane.BUSY_CURSOR
				: MGlassPane.NORMAL_CURSOR);
		glassPane.setVisible(busy);
	}
}

